pub fn assert_identity(&self) -> Result<(), String> {
    return same_file_identity(self.lock_path.as_path(), &self.identity);
}

/// What:
///  Release the lock and this process's PID file,
///  refusing a lock that was replaced.
/// Why:
///   A replaced lock belongs to another process and stays in place.
///
/// In TS you'd write (pseudocode):
/// ```ts
/// await lock[Symbol.asyncDispose]();
/// ```
pub fn release(self) -> Result<(), String> {
    self.assert_identity()?;
    if let Err(error) = std::fs::remove_file(&self.lock_path) {
        return Err(error.to_string());
    }
    return remove_own_pid_file(self.pid_path.as_path());

pub fn install(self, post_index: &Path) -> Result<(), RecoveryError> {
    install_recovered_index(
        self.lock_path.as_path(),
        self.real_index.as_path(),
        post_index,
        &self.identity,
    )?;
    debug(TAG, format!("installed {} through {}", self.real_index.display(), self.lock_path.display()).as_str());
    return remove_own_pid_file(self.pid_path.as_path()).map_err(RecoveryError);

pub fn release_after_landing(self) -> Result<(), String> {
    match release_owned_lock(&self.identity, self.lock_path.as_path()) {
        Ok(LockRelease::Released) => {}
        Ok(other) => warn(
            TAG,
            format!("index lock was not this transaction's at release ({}): {}", lock_release_name(other), self.lock_path.display()).as_str(),
        ),
        Err(error) => return Err(error.0),
    }
    return remove_own_pid_file(self.pid_path.as_path());

fn same_file_identity(path: &Path, identity: &LockIdentity) -> Result<(), String> {
    use std::os::unix::fs::MetadataExt;
    let metadata: std::fs::Metadata = match std::fs::symlink_metadata(path) {
        Ok(found) => found,
        Err(error) => return Err(error.to_string()),
    };
    if !metadata.is_file()
        || metadata.dev().to_string() != identity.file.device
        || metadata.ino().to_string() != identity.file.inode
    {
        return Err(format!("the index lock identity changed: {}", path.display()));
    }
    return Ok(());
}

pub fn file_identity_of(path: &Path) -> std::io::Result<(String, String, bool)> {
    let metadata: std::fs::Metadata = std::fs::symlink_metadata(path)?;
    return Ok(metadata_identity(&metadata));
}

/// What:
///  The device,
///  inode and regular-file flag of metadata.
/// Why:
///   Shared by path and descriptor identities.
///
/// In TS you'd write (pseudocode):
/// ```ts
/// [String(metadata.dev), String(metadata.ino), metadata.isFile()]
/// ```
pub fn metadata_identity(metadata: &std::fs::Metadata) -> (String, String, bool) {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt;
        return (
            metadata.dev().to_string(),
            metadata.ino().to_string(),
            metadata.file_type().is_file(),
        );

pub fn assert_owned_lock(journal: &LockIdentity, lock_path: &Path) -> Result<(), RecoveryError> {
    if let Some(mismatch) = owned_lock_mismatch(journal, lock_path)? {
        return Err(RecoveryError(mismatch));
    }
    return Ok(());

pub fn release_owned_lock(
    journal: &LockIdentity,
    lock_path: &Path,
) -> Result<LockRelease, RecoveryError> {
    return release_owned_lock_with(journal, lock_path, filesystem_identity);

fn release_owned_lock_with(
    journal: &LockIdentity,
    lock_path: &Path,
    identity_of_filesystem: fn(&Path) -> Option<String>,
) -> Result<LockRelease, RecoveryError> {
    if !recovery_path_exists(lock_path)? {
        return Ok(LockRelease::Absent);
    }
    let proof: Result<Option<String>, RecoveryError> =
        owned_lock_mismatch_with(journal, lock_path, identity_of_filesystem);
    let proven: Option<String> = match proof {
        Ok(found) => found,
        Err(error) => {
            // Another recoverer of the same dead transaction may have released the lock after the existence
            // probe; a lock that is gone now was released by that peer, whereas one that still exists but
            // cannot be identified stays an error.
            if recovery_path_exists(lock_path)? {
                return Err(error);
            }
