#[cfg(unix)]
fn a_replaced_lock_is_never_released() {
    let (root, index): (PathBuf, PathBuf) = index_in("real-lock-replaced");
    let lock: RealIndexLock = match acquire_real_index_lock(index.as_path(), 100, "did nothing") {
        Ok(found) => found,
        Err(failure) => panic!("a free index is lockable: {failure:?}"),
    };
    let path: PathBuf = real_lock_path(index.as_path());
    std::fs::remove_file(&path).expect("remove the created lock");
    std::fs::write(&path, b"another process's lock").expect("replacement");
    let refusal: String = lock.release().expect_err("a replaced lock must not be released");
    assert!(refusal.contains("identity changed"), "{refusal}");
    assert_eq!(std::fs::read(&path).expect("replacement kept"), b"another process's lock");
    remove(root.as_path());
}

fn an_install_through_a_replaced_lock_is_refused() {
    let (root, index): (PathBuf, PathBuf) = index_in("real-lock-install-replaced");
    let directory: PathBuf = transaction_in(root.as_path());
    std::fs::write(index.as_path(), b"old index").expect("old index");
    let post: PathBuf = directory.join("post-1.index");
    std::fs::write(post.as_path(), b"post index").expect("post index");
    let lock: RealIndexLock = acquire_landing_index_lock(index.as_path(), directory.as_path(), 1, 100, "landed nothing")
        .expect("a free index is lockable");
    let path: PathBuf = real_lock_path(index.as_path());
    std::fs::remove_file(&path).expect("remove the created lock");
    std::fs::write(&path, b"another process's lock").expect("replacement");
    let refusal: RecoveryError = lock.install(post.as_path()).expect_err("a replaced lock must not be written");
    assert!(refusal.0.contains("identity changed"), "{refusal:?}");
    assert_eq!(std::fs::read(index.as_path()).expect("old index kept"), b"old index");
    assert_eq!(std::fs::read(&path).expect("replacement kept"), b"another process's lock");
    remove(root.as_path());

fn releasing_after_a_landing_leaves_a_replaced_lock() {
    let (root, index): (PathBuf, PathBuf) = index_in("real-lock-release-replaced");
    let directory: PathBuf = transaction_in(root.as_path());
    let lock: RealIndexLock = acquire_landing_index_lock(index.as_path(), directory.as_path(), 1, 100, "landed nothing")
        .expect("a free index is lockable");
    let path: PathBuf = real_lock_path(index.as_path());
    std::fs::remove_file(&path).expect("remove the created lock");
    std::fs::write(&path, b"another process's lock").expect("replacement");
    lock.release_after_landing().expect("a replaced lock only warns");
    assert_eq!(std::fs::read(&path).expect("replacement kept"), b"another process's lock");
    assert!(!real_pid_path(index.as_path()).exists());
    remove(root.as_path());

fn a_pid_file_that_cannot_be_created_fails_the_acquisition() {
    let root: PathBuf = crate::test_support::fixture("real-lock-pid-too-long");
    let directory: PathBuf = transaction_in(root.as_path());
    let index: PathBuf = root.join("i".repeat(250));
    let failure: CoordinationFailure =
        match acquire_landing_index_lock(index.as_path(), directory.as_path(), 1, 100, "landed nothing") {
            Ok(_) => panic!("the PID file name is too long"),
            Err(found) => found,
        };
    assert!(matches!(&failure, CoordinationFailure::Stop(text) if text.contains("~pid.lock")), "{failure:?}");
    assert!(!real_lock_path(index.as_path()).exists(), "the lock is removed again");
    remove(root.as_path());

fn input_file(bytes: &[u8]) -> std::io::Result<std::fs::File> {
    let unique: String = match random_uuid() {
        Ok(id) => id,
        Err(error) => return Err(std::io::Error::other(error.0)),
    };
    let path: PathBuf = std::env::temp_dir().join(format!("cli-git-input-{unique}"));
    write_private_file(path.as_path(), bytes)?;
    let file: std::io::Result<std::fs::File> = std::fs::File::open(&path);
    // The open handle keeps the bytes readable after the name is gone. If the platform refuses
    // to remove an open file, the private file stays behind and the error is ignored.
    let _ = std::fs::remove_file(&path);
    let opened: std::fs::File = file?;
    return Ok(opened);

/// Input files are private and already unlinked.
#[cfg(unix)]
#[test]
fn input_files_leave_nothing_behind() {
    use std::io::Read;
    use std::os::unix::fs::MetadataExt;
    let mut file: std::fs::File = input_file(b"bytes").expect("input file");
    let metadata: std::fs::Metadata = file.metadata().expect("metadata");
    assert_eq!(metadata.nlink(), 0);
    assert_eq!(metadata.mode() & 0o777, 0o600);
    let mut read: Vec<u8> = Vec::new();
    file.read_to_end(&mut read).expect("read");
    assert_eq!(read, b"bytes");
}

pub fn is_conflict_error(error: &std::io::Error) -> bool {
    if matches!(
        error.kind(),
        std::io::ErrorKind::NotFound
            | std::io::ErrorKind::NotADirectory
            | std::io::ErrorKind::PermissionDenied
    ) {
        return true;
    }
    #[cfg(unix)]
    {
        return error.raw_os_error() == Some(libc::ELOOP);
    }

pub fn inspect_worktree_file(
    destination: &Path,
    git_mode: &str,
    original: &[u8],
    intended: &[u8],
) -> std::io::Result<WorktreeFileState> {
    match inspect_or_fail(destination, git_mode, original, intended) {
        Ok(state) => return Ok(state),
        Err(error) if is_conflict_error(&error) => return Ok(WorktreeFileState::Conflict),
        Err(error) => return Err(error),
    }

fn inspect_or_fail(
    destination: &Path,
    git_mode: &str,
    original: &[u8],
    intended: &[u8],
) -> std::io::Result<WorktreeFileState> {
    if !directory_is_canonical(destination)? {
        return Ok(WorktreeFileState::Conflict);
    }
    let entry: std::fs::Metadata = std::fs::symlink_metadata(destination)?;
    if !entry.file_type().is_file() || link_count(&entry) != 1 {
        return Ok(WorktreeFileState::Conflict);
    }
    let mut handle: std::fs::File = open_nonblocking(destination)?;
    let opened: std::fs::Metadata = handle.metadata()?;

/// An error that is not one of the conflict codes fails the inspection instead of reading as a conflict.
#[cfg(unix)]
#[test]
fn an_error_that_is_not_a_conflict_fails_the_inspection() {
    let root: PathBuf = fixture("worktree-completion-long-name");
    let long: PathBuf = root.join("x".repeat(300));
    let error = inspect_worktree_file(long.as_path(), "100644", b"a", b"b").expect_err("name too long");
    assert!(!is_conflict_error(&error), "{error:?}");
    remove(root.as_path());

