<summary><code>~/.pi/agent/extensions/bash-poke.ts</code></summary>

```ts
// ~/.pi/agent/extensions/bash-poke.ts
/**
 * bash-poke — makes `!command` trigger a model turn when the command finishes,
 * like Claude Code's bash mode. Commands always run in the background.
 *
 * Behavior:
 * - `!cmd`: returns control to the editor immediately (placeholder output is
 *   recorded in context) and pokes the model with the real output when the
 *   process exits. Multiple commands can run concurrently.
 * - `!!cmd` (hidden): untouched, native pi handling.
 *
 * Differences from native `!`: no live output streaming (output arrives in the
 * poke message), Escape does not cancel (use `/poke cancel`), and concurrent
 * commands are allowed.
 *
 * The poke lands as a normal user message (`deliverAs: "followUp"`), so it sends
 * immediately when idle and queues after current work otherwise. It only fires
 * while this pi process is alive. `/poke` lists background commands,
 * `/poke cancel` aborts them (cancelled commands do not poke).
 *
 * Install: drop in ~/.pi/agent/extensions/, then run `/reload`.
 * Remove:  delete this file, then run `/reload`.
 */
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

/** Poke message output cap, to avoid flooding LLM context. */
const MAX_POKE_CHARS = 8000;

/** Instruction appended to every poke so the model resumes the task. */
const POKE_INSTRUCTION = "continue";

/** Placeholder recorded in context while a background command is still running. */
const PENDING_NOTE = "(running in background; output will be sent when it finishes)";

/** A `!` command running in the background, pokes on exit. */
interface BackgroundJob {
	/** Original command line, for display and the poke message. */
	readonly command: string;
	/** Aborted by `/poke cancel` to suppress the poke. */
	cancelledByUser: boolean;
	readonly controller: AbortController;
}

/** Shape of {@link ExtensionAPI.exec} results. */
interface ExecOutcome {
	readonly stdout: string;
	readonly stderr: string;
	readonly code: number;
	readonly killed: boolean;
}

export default function bashPoke(pi: ExtensionAPI) {
	/** Commands currently running in the background. */
	const jobs = new Set<BackgroundJob>();

	/** Combine stdout and stderr for poke messages. */
	const combinedOutput = (stdout: string, stderr: string): string => (stdout + stderr).trim();

	/** Build the user message that pokes the model after a command finishes. */
	const buildPokeText = (
		command: string,
		output: string,
		exitCode: number | undefined,
		cancelled: boolean,
	): string => {
		const status = cancelled ? "cancelled" : `exit ${exitCode ?? "unknown"}`;
		const body =
			output.length > MAX_POKE_CHARS ? `${output.slice(0, MAX_POKE_CHARS)}\n…[truncated]` : output;
		const outputBlock = body.length > 0 ? `\n\`\`\`\n${body}\n\`\`\`` : "\n(no output)";
		const lines = [`[bash finished] $ ${command} (${status})`, outputBlock];
		if (POKE_INSTRUCTION.length > 0) {
			lines.push("", POKE_INSTRUCTION);
		}
		return lines.join("\n");
	};

	/** Send a user message so the model reacts to the finished command. */
	const poke = (text: string): void => {
		pi.sendUserMessage(text, { deliverAs: "followUp" });
	};

	/** Poke the model with a finished command's output unless the user cancelled it. */
	const reportOutcome = (
		job: BackgroundJob,
		command: string,
		output: string,
		exitCode: number | undefined,
		cancelled: boolean,
	): void => {
		jobs.delete(job);
		if (job.cancelledByUser) {
			return;
		}
		poke(buildPokeText(command, output, exitCode, cancelled));
	};

	pi.on("user_bash", (event) => {
		// `!!` commands are explicitly hidden from the model; leave them to pi.
		if (event.excludeFromContext) {
			return undefined;
		}

		const controller = new AbortController();
		const job: BackgroundJob = { command: event.command, cancelledByUser: false, controller };
		const execPromise = pi.exec("bash", ["-c", event.command], {
			cwd: event.cwd,
			signal: controller.signal,
		});
		execPromise.then(
			(result) => {
				reportOutcome(
					job,
					event.command,
					(result.stdout + result.stderr).trim(),
					result.killed ? undefined : result.code,
					result.killed,
				);
			},
			(error: unknown) => {
				const message = error instanceof Error ? error.message : String(error);
				reportOutcome(job, event.command, `failed to run: ${message}`, undefined, false);
			},
		);
		return {
			result: { output: PENDING_NOTE, exitCode: undefined, cancelled: false, truncated: false },
		};
	});

	pi.registerCommand("poke", {
		description: "List or cancel background ! commands (usage: /poke [cancel])",
		handler: async (args, ctx) => {
			const verb = args.trim();
			if (verb === "cancel" || verb.startsWith("cancel ")) {
				for (const job of jobs) {
					job.cancelledByUser = true;
					job.controller.abort();
				}
				jobs.clear();
				if (ctx.hasUI) {
					ctx.ui.notify("Cancelled background commands", "info");
				}
				return;
			}
			if (jobs.size === 0) {
				if (ctx.hasUI) {
					ctx.ui.notify("No background ! commands running", "info");
				}
				return;
			}
			const lines = [...jobs].map((job, index) => `${index + 1}. ${job.command}`);
			if (ctx.hasUI) {
				ctx.ui.notify(`Background commands:\n${lines.join("\n")}\n/poke cancel to abort all`, "info");
			}
		},
	});
}
